"""Shared helpers for the generators: headers, naming, output locations."""

from __future__ import annotations

import re
from dataclasses import dataclass
from pathlib import Path

from hai_ontology.meta import Manifest

GENERATED_MARK = "generated by hai-ontology"


def header(manifest: Manifest, comment: str) -> str:
    """The 'generated, do not edit' header for a file with the given line comment prefix."""
    return (
        f"{comment} {GENERATED_MARK} from the manifest under ontology/. Do not edit.\n"
        f"{comment} ontology {manifest.ontology_version}, methodology {manifest.methodology_version}, "
        f"ruleset {manifest.ruleset.version}\n"
        f"{comment} manifest hash: {manifest.hash}\n"
    )


def snake(name: str) -> str:
    return re.sub(r"(?<!^)(?=[A-Z])", "_", name).lower()


def const_name(code: str) -> str:
    """A Python or TypeScript identifier for a vocabulary value code."""
    cleaned = re.sub(r"[^0-9A-Za-z]+", "_", code).strip("_").upper()
    if not cleaned:
        cleaned = "VALUE"
    if cleaned[0].isdigit():
        cleaned = "V_" + cleaned
    return cleaned


def pascal(code: str) -> str:
    return "".join(part.capitalize() for part in re.split(r"[^0-9A-Za-z]+", code) if part)


@dataclass(frozen=True)
class Outputs:
    """Where generated files live, relative to the repository root."""

    root: Path

    @property
    def sql_baseline(self) -> Path:
        return self.root / "db" / "migrations" / "0001_ontology_baseline.sql"

    @property
    def python_dir(self) -> Path:
        return self.root / "packages" / "hai-core" / "src" / "hai_core" / "generated"

    @property
    def schema_dir(self) -> Path:
        return self.root / "packages" / "hai-engine" / "src" / "hai_engine" / "generated"

    @property
    def typescript(self) -> Path:
        return self.root / "frontend" / "src" / "generated" / "ontology.ts"

    @property
    def docs_dir(self) -> Path:
        return self.root / "docs" / "generated"
